import{_ as l,a0 as o,w as p,s as d,ao as r,I as t,x as s,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何解密 Linux 版本信息 | LCTT x X-CMD","titleTemplate":false,"description":"如何解密 Linux 版本信息 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何解密 Linux 版本信息 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何解密 Linux 版本信息 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200708 How to decipher Linux release info","title":"如何解密 Linux 版本信息","tag":"202007","desc":""},"relativePath":"202007/20200708 How to decipher Linux release info.md","filePath":"[post].md"}'),c={name:"202007/20200708 How to decipher Linux release info.md"};function u(h,e,g,b,k,m){const a=o("Link");return p(),d("div",null,[e[15]||(e[15]=r(`<h1 id="如何解密-linux-版本信息" tabindex="-1">如何解密 Linux 版本信息 <a class="header-anchor" href="#如何解密-linux-版本信息" aria-label="Permalink to “如何解密 Linux 版本信息”">​</a></h1><blockquote><p>顯示和解釋有關 Linux 版本的信息比看起來要複雜一些。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2020/07/linux_woman-with-laptop_keyboard_code_programmer_devops_by-christin-hume-via-unsplash_linux_-100850842-large.jpg" alt="christin hume / Linux / Modified by IDG Comm."></p><p>與引用一個簡單的版本號不同，識別 Linux 版本有很多種方法。即使只是快速查看一下 <code>uname</code> 命令的輸出，也可以告訴你一些信息。這些信息是什麼，它告訴你什麼？</p><p>在本文中，我們將認真研究 <code>uname</code> 命令的輸出以及其他一些命令和文件提供的版本説明。</p><h3 id="使用-uname" tabindex="-1">使用 uname <a class="header-anchor" href="#使用-uname" aria-label="Permalink to “使用 uname”">​</a></h3><p>每當在 Linux 系統終端窗口中執行命令 <code>uname -a</code> 時，都會顯示很多信息。那是因為這個小小的 <code>a</code> 告訴 <code>uname</code> 命令你想查看該命令能提供的<em>全部</em>輸出。結果顯示的內容將告訴你許多有關該系統的各種信息。實際上，顯示的每一塊信息都會告訴你一些關於系統的不同信息。</p><p>例如，<code>uname -a</code> 輸出看起來像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ uname -a</span></span>
<span class="line"><span>Linux dragonfly 5.4.0-37-generic #41-Ubuntu SMP Wed Jun 3 18:57:02 UTC 2020 x86_64 x86_64 x86_64 GNU/Linux</span></span></code></pre></div><p>儘管這可能不太重要，但你可以使用一個按適當的順序包含 <code>uname</code> 所有選項來顯示相同的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ uname -snmrvpio</span></span>
<span class="line"><span>Linux dragonfly 5.4.0-37-generic #41-Ubuntu SMP Wed Jun 3 18:57:02 UTC 2020 x86_64 x86_64 x86_64 GNU/Linux</span></span></code></pre></div><p>要將這一長串信息分解為單獨的塊，可以使用類似這樣的 <code>for</code> 循環來遍歷每個選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for option in s n m r v p i o; do echo -n &quot;$option: &quot;; uname -$option; done</span></span>
<span class="line"><span>s: Linux</span></span>
<span class="line"><span>n: dragonfly</span></span>
<span class="line"><span>m: x86_64</span></span>
<span class="line"><span>r: 5.4.0-37-generic</span></span>
<span class="line"><span>v: #41-Ubuntu SMP Wed Jun 3 18:57:02 UTC 2020</span></span>
<span class="line"><span>p: x86_64</span></span>
<span class="line"><span>i: x86_64</span></span>
<span class="line"><span>o: GNU/Linux</span></span></code></pre></div><p>該循環顯示了該選項提供了哪些信息。<code>uname</code> 手冊頁提供了每個選項的描述。以下是清單：</p><ul><li>Linux –- 內核名稱（選項 <code>s</code>）</li><li>dragonfly –- 節點名（選項 <code>n</code>）</li><li>x86_64 –- 機器硬件名（選項 <code>m</code>）</li><li>5.4.0-37-generic –- 內核發佈版本（選項 <code>r</code>）</li><li>#41-Ubuntu SMP Wed Jun 3 18:57:02 UTC 2020 -- 內核版本（選項 <code>v</code>）</li><li>x86_64 –- 處理器（選項 <code>p</code>）</li><li>x86_64 –- 硬件平台（選項 <code>i</code>）</li><li>GNU/Linux –- 操作系統（選項 <code>o</code>）</li></ul><p>要更深入地研究顯示的信息，請認真查看顯示的內核發行數據。第四行中的 <code>5.4.0-37</code> 不僅僅是一串任意數字。每個數字都很重要。</p><ul><li><code>5</code> 表示內核版本</li><li><code>4</code> 表示主要版本</li><li><code>0</code> 表示次要版本</li><li><code>37</code> 表示最新補丁</li></ul><p>此外，在上面的循環中輸出的第 5 行（內核版本）中的 <code>#41</code> 表示此發佈版本已編譯 41 次。</p><p>如果你只想顯示所有信息中的一項，那麼單個選項可能很有用。例如，命令 <code>uname -n</code> 可以僅告訴你係統名稱，而 <code>uname -r</code> 僅可以告訴你內核發佈版本。在盤點服務器或構建腳本時，這些和其他選項可能很有用。</p><p>在 Red Hat 系統時，<code>uname -a</code> 命令將提供相同種類的信息。這是一個例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ uname -a</span></span>
<span class="line"><span>Linux fruitfly 4.18.0-107.el8.x86_64 #1 SMP Fri Jun 14 13:46:34 UTC 2019 x86_64 x86_64 x86_64 GNU/Linux</span></span></code></pre></div><h3 id="發行版信息" tabindex="-1">發行版信息 <a class="header-anchor" href="#發行版信息" aria-label="Permalink to “發行版信息”">​</a></h3><p>如果你需要了解運行的發行版是什麼，那麼 <code>uname</code> 的輸出不會對你有太大幫助。畢竟，內核版本與發行版不同。關於這個信息，你可以在 Ubuntu 和其他基於 Debian 的系統上使用 <code>lsb_release -r</code> 命令，而在 Red Hat 上可以顯示 <code>/etc/redhat-release</code> 文件的內容。</p><p>對於 Debian 系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsb_release -r</span></span>
<span class="line"><span>Release: 20.04</span></span></code></pre></div><p>對於 Red Hat 及相關係統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/redhat-release</span></span>
<span class="line"><span>Red Hat Enterprise Linux release 8.1 Beta (Ootpa)</span></span></code></pre></div><h3 id="使用-proc-version" tabindex="-1">使用 /proc/version <a class="header-anchor" href="#使用-proc-version" aria-label="Permalink to “使用 /proc/version”">​</a></h3><p><code>/proc/version</code> 文件還可以提供有關 Linux 版本的信息。該文件中提供的信息與 <code>uname -a</code> 輸出有很多共同點。以下是例子。</p><p>在 Ubuntu 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /proc/version</span></span>
<span class="line"><span>Linux version 5.4.0-37-generic (buildd@lcy01-amd64-001) (gcc version 9.3.0 (Ubuntu 9.3.0-10ubuntu2)) #41-Ubuntu SMP Wed Jun 3 18:57:02 UTC 2020</span></span></code></pre></div><p>在 RedHat 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /proc/version</span></span>
<span class="line"><span>Linux version 4.18.0-107.el8.x86_64 (mockbuild@x86-vm-09.build.eng.bos.redhat.com) (gcc version 8.3.1 20190507 (Red Hat 8.3.1-4) (GCC)) #1 SMP Fri Jun 14 13:46:34 UTC 2019</span></span></code></pre></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>Linux 系統提供了很多關於內核和發行版安裝的信息。你只需要知道在哪裏或如何尋找並理解它的含義。</p><hr>`,36)),t("p",null,[e[1]||(e[1]=s("via: ",-1)),i(a,{href:"https://www.networkworld.com/article/3565432/how-to-decipher-linux-release-info.html"},{default:n(()=>[...e[0]||(e[0]=[s("https://www.networkworld.com/article/3565432/how-to-decipher-linux-release-info.html",-1)])]),_:1})]),t("p",null,[e[6]||(e[6]=s("作者：",-1)),i(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:n(()=>[...e[2]||(e[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),e[7]||(e[7]=s(" 選題：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:n(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[s("Linux中國",-1)])]),_:1}),e[14]||(e[14]=s(" 榮譽推出",-1))])])}const L=l(c,[["render",u]]);export{C as __pageData,L as default};
